CREATE TABLE IF NOT EXISTS vat_validation_events (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL REFERENCES documents(id),
  event_type TEXT NOT NULL CHECK(event_type IN ('inspection','provider_requested','provider_result','preflight_passed','preflight_failed')),
  supplier_country_code TEXT,
  supplier_identifier TEXT,
  classification TEXT NOT NULL CHECK(classification IN ('DK','EU','NON_EU','CONFLICT')),
  provider_status TEXT NOT NULL,
  provider_name TEXT,
  provider_address TEXT,
  actor TEXT,
  evidence_expires_at TEXT,
  detail_json TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_vat_validation_events_document ON vat_validation_events(document_id, id DESC);
CREATE TRIGGER vat_validation_events_no_update BEFORE UPDATE ON vat_validation_events BEGIN SELECT RAISE(ABORT, 'VAT validation events are append-only'); END;
CREATE TRIGGER vat_validation_events_no_delete BEFORE DELETE ON vat_validation_events BEGIN SELECT RAISE(ABORT, 'VAT validation events are append-only'); END;
CREATE TABLE IF NOT EXISTS purchase_posting_applications (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL UNIQUE REFERENCES documents(id),
  application_key TEXT NOT NULL UNIQUE,
  journal_entry_id INTEGER REFERENCES journal_entries(id),
  bank_transaction_id INTEGER REFERENCES bank_transactions(id),
  status TEXT NOT NULL CHECK(status IN ('started','posted')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER purchase_posting_applications_no_update BEFORE UPDATE ON purchase_posting_applications WHEN OLD.status = 'posted' BEGIN SELECT RAISE(ABORT, 'posted purchase applications are append-only'); END;
ALTER TABLE exceptions ADD COLUMN resolution_key TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_exceptions_open_resolution_key ON exceptions(resolution_key) WHERE status = 'open' AND resolution_key IS NOT NULL;
